update public.learning_skill_content content
set title=authored.title, learning_objective=authored.learning_objective, explanation=authored.explanation, worked_example=authored.worked_example, common_misconception=authored.common_misconception, review_notes='Sprint 4 v2 mathematics corrections: requires designated mathematics review before approval.', updated_at=now()
from authored join public.curriculum_skills skill on skill.skill_code=authored.skill_code
where content.curriculum_skill_id=skill.id and content.review_status in ('draft','rejected');

with authored(item_code,prompt,answer_config,solution,reasoning_classification,cognitive_level) as (
values
  ('Q.G9.S4.PRACTICE.REAL.01', 'Which number is irrational?', '{"type":"multiple_choice","options":{"A":"√20","B":"0.25","C":"−7","D":"3/5"},"correct_option":"A","distractor_explanations":{"B":"Choosing “0.25” suggests a calculation step, scale factor, or place value has changed. 20 is not a perfect square, so √20 cannot be written as a ratio of integers. The other choices are rational. Use this check: Check whether the radicand is a perfect square.","C":"Choosing “−7” suggests the sign rule has been applied incorrectly. 20 is not a perfect square, so √20 cannot be written as a ratio of integers. The other choices are rational. Use this check: Check whether the radicand is a perfect square.","D":"Choosing “3/5” suggests a calculation step, scale factor, or place value has changed. 20 is not a perfect square, so √20 cannot be written as a ratio of integers. The other choices are rational. Use this check: Check whether the radicand is a perfect square."}}'::jsonb, '20 is not a perfect square, so √20 cannot be written as a ratio of integers. The other choices are rational.', 'procedural', 'routine'),
  ('Q.G9.S4.PRACTICE.REAL.02', 'Classify √121.', '{"type":"multiple_choice","options":{"A":"Not a real number","B":"A rational integer","C":"An irrational number","D":"A negative integer"},"correct_option":"B","distractor_explanations":{"A":"Choosing “Not a real number” suggests a different operation or condition has been applied than the one in the question. √121 = 11. It is a natural number, an integer and therefore rational. Use this check: Find the principal square root first.","C":"Choosing “An irrational number” suggests a different operation or condition has been applied than the one in the question. √121 = 11. It is a natural number, an integer and therefore rational. Use this check: Find the principal square root first.","D":"Choosing “A negative integer” suggests a different operation or condition has been applied than the one in the question. √121 = 11. It is a natural number, an integer and therefore rational. Use this check: Find the principal square root first."}}'::jsonb, '√121 = 11. It is a natural number, an integer and therefore rational.', 'procedural', 'routine'),
  ('Q.G9.S4.PRACTICE.REAL.03', 'Why is 0.333… rational?', '{"type":"multiple_choice","options":{"A":"It is close to zero","B":"It contains a decimal point","C":"It is equal to 1/3","D":"It has infinitely many digits"},"correct_option":"C","distractor_explanations":{"A":"Choosing “It is close to zero” suggests a different operation or condition has been applied than the one in the question. A recurring decimal has a fractional form. Here 0.333… = 1/3, so it is rational. Use this check: Recurring is different from non-repeating.","B":"Choosing “It contains a decimal point” suggests a different operation or condition has been applied than the one in the question. A recurring decimal has a fractional form. Here 0.333… = 1/3, so it is rational. Use this check: Recurring is different from non-repeating.","D":"Choosing “It has infinitely many digits” suggests a different operation or condition has been applied than the one in the question. A recurring decimal has a fractional form. Here 0.333… = 1/3, so it is rational. Use this check: Recurring is different from non-repeating."}}'::jsonb, 'A recurring decimal has a fractional form. Here 0.333… = 1/3, so it is rational.', 'mathematical_reasoning', 'complex'),
  ('Q.G9.S4.PRACTICE.REAL.04', 'Which statement is correct about √(1/4)?', '{"type":"multiple_choice","options":{"A":"It is irrational because 1/4 is not an integer","B":"It equals 1/16 because both parts are squared","C":"It is not real","D":"It is rational because √(1/4) = 1/2"},"correct_option":"D","distractor_explanations":{"A":"Choosing “It is irrational because 1/4 is not an integer” suggests a calculation step, scale factor, or place value has changed. The principal square root of 1/4 is 1/2 because (1/2)² = 1/4. A rational radicand need not be an integer. Use this check: Which non-negative fraction squared gives 1/4?","B":"Choosing “It equals 1/16 because both parts are squared” suggests a calculation step, scale factor, or place value has changed. The principal square root of 1/4 is 1/2 because (1/2)² = 1/4. A rational radicand need not be an integer. Use this check: Which non-negative fraction squared gives 1/4?","C":"Choosing “It is not real” suggests an absolute statement has replaced the stated mathematical condition. The principal square root of 1/4 is 1/2 because (1/2)² = 1/4. A rational radicand need not be an integer. Use this check: Which non-negative fraction squared gives 1/4?"}}'::jsonb, 'The principal square root of 1/4 is 1/2 because (1/2)² = 1/4. A rational radicand need not be an integer.', 'mathematical_reasoning', 'complex'),
  ('Q.G9.S4.PRACTICE.HCF-LCM.01', 'What is the prime factorisation of 84?', '{"type":"multiple_choice","options":{"A":"2 × 3 × 7","B":"2³ × 3 × 7","C":"2² × 3² × 7","D":"2² × 3 × 7"},"correct_option":"D","distractor_explanations":{"A":"Choosing “2 × 3 × 7” suggests a calculation step, scale factor, or place value has changed. 84 = 4 × 21 = 2² × 3 × 7. Use this check: Keep dividing by prime numbers.","B":"Choosing “2³ × 3 × 7” suggests a calculation step, scale factor, or place value has changed. 84 = 4 × 21 = 2² × 3 × 7. Use this check: Keep dividing by prime numbers.","C":"Choosing “2² × 3² × 7” suggests a calculation step, scale factor, or place value has changed. 84 = 4 × 21 = 2² × 3 × 7. Use this check: Keep dividing by prime numbers."}}'::jsonb, '84 = 4 × 21 = 2² × 3 × 7.', 'procedural', 'routine'),
  ('Q.G9.S4.PRACTICE.HCF-LCM.02', 'Find the HCF of 30 and 45.', '{"type":"multiple_choice","options":{"A":"15","B":"5","C":"10","D":"90"},"correct_option":"A","distractor_explanations":{"B":"Choosing “5” suggests a calculation step, scale factor, or place value has changed. 30 = 2 × 3 × 5 and 45 = 3² × 5. The common factors are 3 and 5, so the HCF is 15. Use this check: List the prime factors of both numbers.","C":"Choosing “10” suggests a calculation step, scale factor, or place value has changed. 30 = 2 × 3 × 5 and 45 = 3² × 5. The common factors are 3 and 5, so the HCF is 15. Use this check: List the prime factors of both numbers.","D":"Choosing “90” suggests a calculation step, scale factor, or place value has changed. 30 = 2 × 3 × 5 and 45 = 3² × 5. The common factors are 3 and 5, so the HCF is 15. Use this check: List the prime factors of both numbers."}}'::jsonb, '30 = 2 × 3 × 5 and 45 = 3² × 5. The common factors are 3 and 5, so the HCF is 15.', 'procedural', 'routine'),
  ('Q.G9.S4.PRACTICE.HCF-LCM.03', 'Two buses arrive together at the starting time, then every 12 and 18 minutes. How many minutes later do they next arrive together?', '{"type":"multiple_choice","options":{"A":"216 minutes","B":"36 minutes","C":"6 minutes","D":"30 minutes"},"correct_option":"B","distractor_explanations":{"A":"Choosing “216 minutes” suggests a calculation step, scale factor, or place value has changed. Starting together means the next shared arrival is the LCM. LCM(12,18) = 36. Use this check: A future time must be a multiple of both intervals.","C":"Choosing “6 minutes” suggests a calculation step, scale factor, or place value has changed. Starting together means the next shared arrival is the LCM. LCM(12,18) = 36. Use this check: A future time must be a multiple of both intervals.","D":"Choosing “30 minutes” suggests a calculation step, scale factor, or place value has changed. Starting together means the next shared arrival is the LCM. LCM(12,18) = 36. Use this check: A future time must be a multiple of both intervals."}}'::jsonb, 'Starting together means the next shared arrival is the LCM. LCM(12,18) = 36.', 'mathematical_reasoning', 'complex'),
  ('Q.G9.S4.PRACTICE.HCF-LCM.04', 'A learner says the HCF of 16 and 24 is 384. What is the correction?', '{"type":"multiple_choice","options":{"A":"HCF is 384, because numbers are multiplied","B":"HCF is 16, because it is the smaller number","C":"HCF is 8, the greatest factor common to both","D":"HCF is 40, because factors are added"},"correct_option":"C","distractor_explanations":{"A":"Choosing “HCF is 384, because numbers are multiplied” suggests a calculation step, scale factor, or place value has changed. 16 = 2⁴ and 24 = 2³ × 3. The common part is 2³ = 8. Use this check: HCF describes a shared divisor, not a product.","B":"Choosing “HCF is 16, because it is the smaller number” suggests a calculation step, scale factor, or place value has changed. 16 = 2⁴ and 24 = 2³ × 3. The common part is 2³ = 8. Use this check: HCF describes a shared divisor, not a product.","D":"Choosing “HCF is 40, because factors are added” suggests a calculation step, scale factor, or place value has changed. 16 = 2⁴ and 24 = 2³ × 3. The common part is 2³ = 8. Use this check: HCF describes a shared divisor, not a product."}}'::jsonb, '16 = 2⁴ and 24 = 2³ × 3. The common part is 2³ = 8.', 'mathematical_reasoning', 'complex'),
  ('Q.G9.S4.PRACTICE.RATIO-RATE.01', 'Simplify 18 : 24.', '{"type":"multiple_choice","options":{"A":"9 : 12","B":"42 : 1","C":"3 : 4","D":"6 : 8 : 2"},"correct_option":"C","distractor_explanations":{"A":"Choosing “9 : 12” suggests a calculation step, scale factor, or place value has changed. The HCF of 18 and 24 is 6. Divide both parts: 18 ÷ 6 : 24 ÷ 6 = 3 : 4. Use this check: Find a number that divides both parts.","B":"Choosing “42 : 1” suggests a calculation step, scale factor, or place value has changed. The HCF of 18 and 24 is 6. Divide both parts: 18 ÷ 6 : 24 ÷ 6 = 3 : 4. Use this check: Find a number that divides both parts.","D":"Choosing “6 : 8 : 2” suggests a calculation step, scale factor, or place value has changed. The HCF of 18 and 24 is 6. Divide both parts: 18 ÷ 6 : 24 ÷ 6 = 3 : 4. Use this check: Find a number that divides both parts."}}'::jsonb, 'The HCF of 18 and 24 is 6. Divide both parts: 18 ÷ 6 : 24 ÷ 6 = 3 : 4.', 'procedural', 'routine'),
  ('Q.G9.S4.PRACTICE.RATIO-RATE.02', 'A taxi travels 150 km in 3 hours. What is its average speed?', '{"type":"multiple_choice","options":{"A":"153 km/h","B":"450 km/h","C":"47 km/h","D":"50 km/h"},"correct_option":"D","distractor_explanations":{"A":"Choosing “153 km/h” suggests a calculation step, scale factor, or place value has changed. Speed = distance ÷ time = 150 ÷ 3 = 50 km/h. Use this check: A unit rate means “for one hour”.","B":"Choosing “450 km/h” suggests a calculation step, scale factor, or place value has changed. Speed = distance ÷ time = 150 ÷ 3 = 50 km/h. Use this check: A unit rate means “for one hour”.","C":"Choosing “47 km/h” suggests a calculation step, scale factor, or place value has changed. Speed = distance ÷ time = 150 ÷ 3 = 50 km/h. Use this check: A unit rate means “for one hour”."}}'::jsonb, 'Speed = distance ÷ time = 150 ÷ 3 = 50 km/h.', 'procedural', 'routine'),
  ('Q.G9.S4.PRACTICE.RATIO-RATE.03', 'Paint is mixed red : white = 2 : 5. If 6 cups are red, how many cups are white?', '{"type":"multiple_choice","options":{"A":"15 cups","B":"11 cups","C":"30 cups","D":"5 cups"},"correct_option":"A","distractor_explanations":{"B":"Choosing “11 cups” suggests a calculation step, scale factor, or place value has changed. Red changes from 2 to 6, so multiply by 3. White is 5 × 3 = 15 cups. Use this check: Find the scale factor first.","C":"Choosing “30 cups” suggests a calculation step, scale factor, or place value has changed. Red changes from 2 to 6, so multiply by 3. White is 5 × 3 = 15 cups. Use this check: Find the scale factor first.","D":"Choosing “5 cups” suggests a calculation step, scale factor, or place value has changed. Red changes from 2 to 6, so multiply by 3. White is 5 × 3 = 15 cups. Use this check: Find the scale factor first."}}'::jsonb, 'Red changes from 2 to 6, so multiply by 3. White is 5 × 3 = 15 cups.', 'mathematical_reasoning', 'complex'),
  ('Q.G9.S4.PRACTICE.RATIO-RATE.04', 'A learner claims that 4 : 6 and 10 : 15 are not equivalent. Which explanation correctly evaluates the claim?', '{"type":"multiple_choice","options":{"A":"The claim is incorrect because all ratios are equivalent","B":"The claim is incorrect: 4 : 6 = 2 : 3 and 10 : 15 = 2 : 3","C":"The claim is correct because the numbers in each ratio are different","D":"The claim is correct because only ratios already in lowest terms can be equivalent"},"correct_option":"B","distractor_explanations":{"A":"Choosing “The claim is incorrect because all ratios are equivalent” suggests a different operation or condition has been applied than the one in the question. Simplify each ratio by its own common factor: 4 : 6 ÷ 2 = 2 : 3 and 10 : 15 ÷ 5 = 2 : 3. Both describe the same multiplicative relationship, so the learner’s claim is incorrect. Use this check: Simplify both ratios before deciding.","C":"Choosing “The claim is correct because the numbers in each ratio are different” suggests a different operation or condition has been applied than the one in the question. Simplify each ratio by its own common factor: 4 : 6 ÷ 2 = 2 : 3 and 10 : 15 ÷ 5 = 2 : 3. Both describe the same multiplicative relationship, so the learner’s claim is incorrect. Use this check: Simplify both ratios before deciding.","D":"Choosing “The claim is correct because only ratios already in lowest terms can be equivalent” suggests a different operation or condition has been applied than the one in the question. Simplify each ratio by its own common factor: 4 : 6 ÷ 2 = 2 : 3 and 10 : 15 ÷ 5 = 2 : 3. Both describe the same multiplicative relationship, so the learner’s claim is incorrect. Use this check: Simplify both ratios before deciding."}}'::jsonb, 'Simplify each ratio by its own common factor: 4 : 6 ÷ 2 = 2 : 3 and 10 : 15 ÷ 5 = 2 : 3. Both describe the same multiplicative relationship, so the learner’s claim is incorrect.', 'mathematical_reasoning', 'complex'),
  ('Q.G9.S4.PRACTICE.PROPORTION.01', 'Five notebooks cost R40. What do eight cost at the same price?', '{"type":"multiple_choice","options":{"A":"R320","B":"R13","C":"R64","D":"R48"},"correct_option":"C","distractor_explanations":{"A":"Choosing “R320” suggests a calculation step, scale factor, or place value has changed. One notebook costs R40 ÷ 5 = R8. Eight cost 8 × R8 = R64. Use this check: Find the cost of one notebook.","B":"Choosing “R13” suggests a calculation step, scale factor, or place value has changed. One notebook costs R40 ÷ 5 = R8. Eight cost 8 × R8 = R64. Use this check: Find the cost of one notebook.","D":"Choosing “R48” suggests a calculation step, scale factor, or place value has changed. One notebook costs R40 ÷ 5 = R8. Eight cost 8 × R8 = R64. Use this check: Find the cost of one notebook."}}'::jsonb, 'One notebook costs R40 ÷ 5 = R8. Eight cost 8 × R8 = R64.', 'procedural', 'routine'),
  ('Q.G9.S4.PRACTICE.PROPORTION.02', 'Eight taps fill a tank in 6 hours. How long would 12 identical taps take?', '{"type":"multiple_choice","options":{"A":"9 hours","B":"18 hours","C":"6 hours","D":"4 hours"},"correct_option":"D","distractor_explanations":{"A":"Choosing “9 hours” suggests a calculation step, scale factor, or place value has changed. The work is 8 × 6 = 48 tap-hours. 48 ÷ 12 = 4 hours. Use this check: For inverse proportion, multiply first then divide.","B":"Choosing “18 hours” suggests a calculation step, scale factor, or place value has changed. The work is 8 × 6 = 48 tap-hours. 48 ÷ 12 = 4 hours. Use this check: For inverse proportion, multiply first then divide.","C":"Choosing “6 hours” suggests a calculation step, scale factor, or place value has changed. The work is 8 × 6 = 48 tap-hours. 48 ÷ 12 = 4 hours. Use this check: For inverse proportion, multiply first then divide."}}'::jsonb, 'The work is 8 × 6 = 48 tap-hours. 48 ÷ 12 = 4 hours.', 'procedural', 'routine'),
  ('Q.G9.S4.PRACTICE.PROPORTION.03', 'Which situation is inverse proportion?', '{"type":"multiple_choice","options":{"A":"For a fixed trip, higher speed means less travel time","B":"More loaves cost more at one price","C":"More litres give a higher water bill","D":"More pages mean more printing"},"correct_option":"A","distractor_explanations":{"B":"Choosing “More loaves cost more at one price” suggests a different operation or condition has been applied than the one in the question. For the same distance, speed × time is fixed. Increasing speed decreases time. Use this check: Look for a fixed total task or distance.","C":"Choosing “More litres give a higher water bill” suggests a different operation or condition has been applied than the one in the question. For the same distance, speed × time is fixed. Increasing speed decreases time. Use this check: Look for a fixed total task or distance.","D":"Choosing “More pages mean more printing” suggests a different operation or condition has been applied than the one in the question. For the same distance, speed × time is fixed. Increasing speed decreases time. Use this check: Look for a fixed total task or distance."}}'::jsonb, 'For the same distance, speed × time is fixed. Increasing speed decreases time.', 'mathematical_reasoning', 'complex'),
  ('Q.G9.S4.PRACTICE.PROPORTION.04', 'A learner doubles workers and doubles days. What error was made?', '{"type":"multiple_choice","options":{"A":"They should add workers and days","B":"They treated an inverse relationship as direct","C":"They simplified the ratio too far","D":"They forgot a decimal point"},"correct_option":"B","distractor_explanations":{"A":"Choosing “They should add workers and days” suggests a different operation or condition has been applied than the one in the question. For the same job, doubling workers halves the time. The worker-day total stays constant. Use this check: Test the answer: would more workers really take longer?","C":"Choosing “They simplified the ratio too far” suggests a different operation or condition has been applied than the one in the question. For the same job, doubling workers halves the time. The worker-day total stays constant. Use this check: Test the answer: would more workers really take longer?","D":"Choosing “They forgot a decimal point” suggests a different operation or condition has been applied than the one in the question. For the same job, doubling workers halves the time. The worker-day total stays constant. Use this check: Test the answer: would more workers really take longer?"}}'::jsonb, 'For the same job, doubling workers halves the time. The worker-day total stays constant.', 'mathematical_reasoning', 'complex'),
  ('Q.G9.S4.PRACTICE.FINANCE.01', 'What is 7% commission on R3 000?', '{"type":"multiple_choice","options":{"A":"R21","B":"R2 790","C":"R700","D":"R210"},"correct_option":"D","distractor_explanations":{"A":"Choosing “R21” suggests a calculation step, scale factor, or place value has changed. 7% = 0.07. R3 000 × 0.07 = R210. Use this check: Change the percent to a decimal.","B":"Choosing “R2 790” suggests a calculation step, scale factor, or place value has changed. 7% = 0.07. R3 000 × 0.07 = R210. Use this check: Change the percent to a decimal.","C":"Choosing “R700” suggests a calculation step, scale factor, or place value has changed. 7% = 0.07. R3 000 × 0.07 = R210. Use this check: Change the percent to a decimal."}}'::jsonb, '7% = 0.07. R3 000 × 0.07 = R210.', 'procedural', 'routine'),
  ('Q.G9.S4.PRACTICE.FINANCE.02', 'A bike rents for R80 per day and requires a refundable R50 deposit paid at collection. What is paid upfront for 3 days, and what is the net rental cost after the deposit is returned?', '{"type":"multiple_choice","options":{"A":"R290 upfront; R240 net rental","B":"R390 upfront; R390 net rental","C":"R240 upfront; R240 net rental","D":"R290 upfront; R290 net rental"},"correct_option":"A","distractor_explanations":{"B":"Choosing “R390 upfront; R390 net rental” suggests a calculation step, scale factor, or place value has changed. The 3-day rental fee is 3 × R80 = R240. The R50 deposit is added once at collection, so R290 is paid upfront; because it is refundable, the net rental cost after return is R240. Use this check: Separate the once-off refundable deposit from the rental fee.","C":"Choosing “R240 upfront; R240 net rental” suggests a calculation step, scale factor, or place value has changed. The 3-day rental fee is 3 × R80 = R240. The R50 deposit is added once at collection, so R290 is paid upfront; because it is refundable, the net rental cost after return is R240. Use this check: Separate the once-off refundable deposit from the rental fee.","D":"Choosing “R290 upfront; R290 net rental” suggests a calculation step, scale factor, or place value has changed. The 3-day rental fee is 3 × R80 = R240. The R50 deposit is added once at collection, so R290 is paid upfront; because it is refundable, the net rental cost after return is R240. Use this check: Separate the once-off refundable deposit from the rental fee."}}'::jsonb, 'The 3-day rental fee is 3 × R80 = R240. The R50 deposit is added once at collection, so R290 is paid upfront; because it is refundable, the net rental cost after return is R240.', 'procedural', 'routine'),
  ('Q.G9.S4.PRACTICE.FINANCE.03', 'R1 500 grows by 8% compound interest for two years. What is the balance?', '{"type":"multiple_choice","options":{"A":"R1 620.80","B":"R1 749.60","C":"R1 620.00","D":"R1 740.00"},"correct_option":"B","distractor_explanations":{"A":"Choosing “R1 620.80” suggests a calculation step, scale factor, or place value has changed. Year 1: 1500 × 1.08 = 1620. Year 2: 1620 × 1.08 = 1749.60. Use this check: Apply 8% to the new balance in year 2.","C":"Choosing “R1 620.00” suggests a calculation step, scale factor, or place value has changed. Year 1: 1500 × 1.08 = 1620. Year 2: 1620 × 1.08 = 1749.60. Use this check: Apply 8% to the new balance in year 2.","D":"Choosing “R1 740.00” suggests a calculation step, scale factor, or place value has changed. Year 1: 1500 × 1.08 = 1620. Year 2: 1620 × 1.08 = 1749.60. Use this check: Apply 8% to the new balance in year 2."}}'::jsonb, 'Year 1: 1500 × 1.08 = 1620. Year 2: 1620 × 1.08 = 1749.60.', 'mathematical_reasoning', 'complex'),
  ('Q.G9.S4.PRACTICE.FINANCE.04', 'Why is compound interest greater than simple interest after two positive years?', '{"type":"multiple_choice","options":{"A":"The original balance is ignored","B":"Interest is subtracted first","C":"Second-year interest is earned on the increased balance","D":"The percentage doubles automatically"},"correct_option":"C","distractor_explanations":{"A":"Choosing “The original balance is ignored” suggests a different operation or condition has been applied than the one in the question. Compound interest adds year-one interest to the balance before calculating year two. Use this check: Compare the base used in the second year.","B":"Choosing “Interest is subtracted first” suggests a different operation or condition has been applied than the one in the question. Compound interest adds year-one interest to the balance before calculating year two. Use this check: Compare the base used in the second year.","D":"Choosing “The percentage doubles automatically” suggests a different operation or condition has been applied than the one in the question. Compound interest adds year-one interest to the balance before calculating year two. Use this check: Compare the base used in the second year."}}'::jsonb, 'Compound interest adds year-one interest to the balance before calculating year two.', 'mathematical_reasoning', 'complex'),
  ('Q.G9.S4.PRACTICE.INTEGER-OPS.01', 'Calculate −8 + 13.', '{"type":"multiple_choice","options":{"A":"−21","B":"−5","C":"21","D":"5"},"correct_option":"D","distractor_explanations":{"A":"Choosing “−21” suggests the sign rule has been applied incorrectly. Starting at −8 and adding 13 gives 5. Use this check: A positive addend moves right.","B":"Choosing “−5” suggests the sign rule has been applied incorrectly. Starting at −8 and adding 13 gives 5. Use this check: A positive addend moves right.","C":"Choosing “21” suggests a calculation step, scale factor, or place value has changed. Starting at −8 and adding 13 gives 5. Use this check: A positive addend moves right."}}'::jsonb, 'Starting at −8 and adding 13 gives 5.', 'procedural', 'routine'),
  ('Q.G9.S4.PRACTICE.INTEGER-OPS.02', 'Calculate (−7) × 6.', '{"type":"multiple_choice","options":{"A":"−42","B":"42","C":"−13","D":"13"},"correct_option":"A","distractor_explanations":{"B":"Choosing “42” suggests a calculation step, scale factor, or place value has changed. The signs differ, so the product is negative. 7 × 6 = 42. Use this check: Check whether the signs match.","C":"Choosing “−13” suggests a calculation step, scale factor, or place value has changed. The signs differ, so the product is negative. 7 × 6 = 42. Use this check: Check whether the signs match.","D":"Choosing “13” suggests a calculation step, scale factor, or place value has changed. The signs differ, so the product is negative. 7 × 6 = 42. Use this check: Check whether the signs match."}}'::jsonb, 'The signs differ, so the product is negative. 7 × 6 = 42.', 'procedural', 'routine'),
  ('Q.G9.S4.PRACTICE.INTEGER-OPS.03', 'Calculate 18 ÷ [3 + (−6)].', '{"type":"multiple_choice","options":{"A":"−3","B":"−6","C":"6","D":"0"},"correct_option":"B","distractor_explanations":{"A":"Choosing “−3” suggests a calculation step, scale factor, or place value has changed. Evaluate the bracket: 3 + (−6) = −3. Then 18 ÷ −3 = −6. Use this check: Brackets are calculated first.","C":"Choosing “6” suggests a calculation step, scale factor, or place value has changed. Evaluate the bracket: 3 + (−6) = −3. Then 18 ÷ −3 = −6. Use this check: Brackets are calculated first.","D":"Choosing “0” suggests a calculation step, scale factor, or place value has changed. Evaluate the bracket: 3 + (−6) = −3. Then 18 ÷ −3 = −6. Use this check: Brackets are calculated first."}}'::jsonb, 'Evaluate the bracket: 3 + (−6) = −3. Then 18 ÷ −3 = −6.', 'mathematical_reasoning', 'complex'),
  ('Q.G9.S4.PRACTICE.INTEGER-OPS.04', 'Why is −4 − 7 equal to −11?', '{"type":"multiple_choice","options":{"A":"Only 7 is negative","B":"All subtraction answers are negative","C":"Subtracting 7 moves 7 units left from −4","D":"The signs cancel"},"correct_option":"C","distractor_explanations":{"A":"Choosing “Only 7 is negative” suggests a calculation step, scale factor, or place value has changed. On a number line start at −4 and move seven units left, reaching −11. Use this check: Think about direction on a number line.","B":"Choosing “All subtraction answers are negative” suggests a different operation or condition has been applied than the one in the question. On a number line start at −4 and move seven units left, reaching −11. Use this check: Think about direction on a number line.","D":"Choosing “The signs cancel” suggests a different operation or condition has been applied than the one in the question. On a number line start at −4 and move seven units left, reaching −11. Use this check: Think about direction on a number line."}}'::jsonb, 'On a number line start at −4 and move seven units left, reaching −11.', 'mathematical_reasoning', 'complex'),
  ('Q.G9.S4.PRACTICE.POWERS-ROOTS.01', 'What is (−5)²?', '{"type":"multiple_choice","options":{"A":"25","B":"−25","C":"−10","D":"10"},"correct_option":"A","distractor_explanations":{"B":"−25 keeps a negative sign after squaring. The bracket makes both factors negative, and (−5) × (−5) is +25.","C":"−10 doubles −5 instead of squaring it. Squaring means multiplying the base by itself: (−5) × (−5).","D":"10 treats the exponent as an instruction to change the sign or add. Expand (−5)² as (−5) × (−5), which is 25."}}'::jsonb, '(−5)² = (−5) × (−5) = 25.', 'procedural', 'routine'),
  ('Q.G9.S4.PRACTICE.POWERS-ROOTS.02', 'What is ∛(−216)?', '{"type":"multiple_choice","options":{"A":"36","B":"−6","C":"6","D":"−36"},"correct_option":"B","distractor_explanations":{"A":"Choosing “36” suggests a calculation step, scale factor, or place value has changed. (−6) × (−6) × (−6) = −216. Use this check: Which negative number cubed gives −216?","C":"Choosing “6” suggests a calculation step, scale factor, or place value has changed. (−6) × (−6) × (−6) = −216. Use this check: Which negative number cubed gives −216?","D":"Choosing “−36” suggests a calculation step, scale factor, or place value has changed. (−6) × (−6) × (−6) = −216. Use this check: Which negative number cubed gives −216?"}}'::jsonb, '(−6) × (−6) × (−6) = −216.', 'procedural', 'routine'),
  ('Q.G9.S4.PRACTICE.POWERS-ROOTS.03', 'Evaluate −3².', '{"type":"multiple_choice","options":{"A":"−6","B":"6","C":"−9","D":"9"},"correct_option":"C","distractor_explanations":{"A":"Choosing “−6” suggests a calculation step, scale factor, or place value has changed. The exponent applies to 3 first: −3² = −(3²) = −9. Use this check: There are no brackets around −3.","B":"Choosing “6” suggests a calculation step, scale factor, or place value has changed. The exponent applies to 3 first: −3² = −(3²) = −9. Use this check: There are no brackets around −3.","D":"Choosing “9” suggests a calculation step, scale factor, or place value has changed. The exponent applies to 3 first: −3² = −(3²) = −9. Use this check: There are no brackets around −3."}}'::jsonb, 'The exponent applies to 3 first: −3² = −(3²) = −9.', 'mathematical_reasoning', 'complex'),
  ('Q.G9.S4.PRACTICE.POWERS-ROOTS.04', 'Why is √64 not ±8?', '{"type":"multiple_choice","options":{"A":"Square roots have no value","B":"Both signs are always written","C":"64 has only one square root equation","D":"√ means the principal non-negative root"},"correct_option":"D","distractor_explanations":{"A":"Choosing “Square roots have no value” suggests a different operation or condition has been applied than the one in the question. The equation x² = 64 has ±8 solutions, but the symbol √64 is defined as the principal root 8. Use this check: Separate a root symbol from solving an equation.","B":"Choosing “Both signs are always written” suggests an absolute statement has replaced the stated mathematical condition. The equation x² = 64 has ±8 solutions, but the symbol √64 is defined as the principal root 8. Use this check: Separate a root symbol from solving an equation.","C":"Choosing “64 has only one square root equation” suggests a different operation or condition has been applied than the one in the question. The equation x² = 64 has ±8 solutions, but the symbol √64 is defined as the principal root 8. Use this check: Separate a root symbol from solving an equation."}}'::jsonb, 'The equation x² = 64 has ±8 solutions, but the symbol √64 is defined as the principal root 8.', 'mathematical_reasoning', 'complex'),
  ('Q.G9.S4.PRACTICE.EXP-LAWS.01', 'Simplify a⁴ × a³.', '{"type":"multiple_choice","options":{"A":"a⁷","B":"a¹²","C":"a¹","D":"7a"},"correct_option":"A","distractor_explanations":{"B":"Choosing “a¹²” suggests a different operation or condition has been applied than the one in the question. The bases match, so add exponents: 4 + 3 = 7. Use this check: The base remains a.","C":"Choosing “a¹” suggests a different operation or condition has been applied than the one in the question. The bases match, so add exponents: 4 + 3 = 7. Use this check: The base remains a.","D":"Choosing “7a” suggests a different operation or condition has been applied than the one in the question. The bases match, so add exponents: 4 + 3 = 7. Use this check: The base remains a."}}'::jsonb, 'The bases match, so add exponents: 4 + 3 = 7.', 'procedural', 'routine'),
  ('Q.G9.S4.PRACTICE.EXP-LAWS.02', 'For y ≠ 0, simplify y⁹ ÷ y⁴.', '{"type":"multiple_choice","options":{"A":"1/y⁵","B":"y⁵","C":"y¹³","D":"y³⁶"},"correct_option":"B","distractor_explanations":{"A":"Choosing “1/y⁵” suggests a different operation or condition has been applied than the one in the question. Because y ≠ 0, the quotient is defined. For division with the same base, subtract: 9 − 4 = 5. Use this check: Use the quotient law only after checking the divisor is non-zero.","C":"Choosing “y¹³” suggests an exponent or operation has been used in place of the required inverse operation. Because y ≠ 0, the quotient is defined. For division with the same base, subtract: 9 − 4 = 5. Use this check: Use the quotient law only after checking the divisor is non-zero.","D":"Choosing “y³⁶” suggests an exponent or operation has been used in place of the required inverse operation. Because y ≠ 0, the quotient is defined. For division with the same base, subtract: 9 − 4 = 5. Use this check: Use the quotient law only after checking the divisor is non-zero."}}'::jsonb, 'Because y ≠ 0, the quotient is defined. For division with the same base, subtract: 9 − 4 = 5.', 'procedural', 'routine'),
  ('Q.G9.S4.PRACTICE.EXP-LAWS.03', 'Simplify (m²n³)².', '{"type":"multiple_choice","options":{"A":"m⁴n⁹","B":"m²n⁶","C":"m⁴n⁶","D":"m⁴n⁵"},"correct_option":"C","distractor_explanations":{"A":"Choosing “m⁴n⁹” suggests a different operation or condition has been applied than the one in the question. Apply the outer power to each factor: m^(2×2)n^(3×2). Use this check: Every exponent inside the bracket is multiplied.","B":"Choosing “m²n⁶” suggests a different operation or condition has been applied than the one in the question. Apply the outer power to each factor: m^(2×2)n^(3×2). Use this check: Every exponent inside the bracket is multiplied.","D":"Choosing “m⁴n⁵” suggests a different operation or condition has been applied than the one in the question. Apply the outer power to each factor: m^(2×2)n^(3×2). Use this check: Every exponent inside the bracket is multiplied."}}'::jsonb, 'Apply the outer power to each factor: m^(2×2)n^(3×2).', 'mathematical_reasoning', 'complex'),
  ('Q.G9.S4.PRACTICE.EXP-LAWS.04', 'A learner writes x² + x³ = x⁵. What is correct?', '{"type":"multiple_choice","options":{"A":"The answer is always x⁵","B":"Add the bases instead","C":"Subtract the exponents","D":"The product law applies to multiplication, not addition"},"correct_option":"D","distractor_explanations":{"A":"Choosing “The answer is always x⁵” suggests an absolute statement has replaced the stated mathematical condition. x² and x³ are unlike terms, so they do not combine through an exponent law. Use this check: Look at the operation between the terms.","B":"Choosing “Add the bases instead” suggests a different operation or condition has been applied than the one in the question. x² and x³ are unlike terms, so they do not combine through an exponent law. Use this check: Look at the operation between the terms.","C":"Choosing “Subtract the exponents” suggests a different operation or condition has been applied than the one in the question. x² and x³ are unlike terms, so they do not combine through an exponent law. Use this check: Look at the operation between the terms."}}'::jsonb, 'x² and x³ are unlike terms, so they do not combine through an exponent law.', 'mathematical_reasoning', 'complex'),
  ('Q.G9.S4.PRACTICE.EXP-ZERO-NEGATIVE.01', 'What is 9⁰?', '{"type":"multiple_choice","options":{"A":"Undefined","B":"1","C":"0","D":"9"},"correct_option":"B","distractor_explanations":{"A":"Choosing “Undefined” suggests an absolute statement has replaced the stated mathematical condition. Any non-zero number to exponent zero equals 1. Use this check: The base is non-zero.","C":"Choosing “0” suggests a calculation step, scale factor, or place value has changed. Any non-zero number to exponent zero equals 1. Use this check: The base is non-zero.","D":"Choosing “9” suggests a calculation step, scale factor, or place value has changed. Any non-zero number to exponent zero equals 1. Use this check: The base is non-zero."}}'::jsonb, 'Any non-zero number to exponent zero equals 1.', 'procedural', 'routine'),
  ('Q.G9.S4.PRACTICE.EXP-ZERO-NEGATIVE.02', 'What is 10⁻²?', '{"type":"multiple_choice","options":{"A":"100","B":"−0.01","C":"0.01","D":"−100"},"correct_option":"C","distractor_explanations":{"A":"Choosing “100” suggests a calculation step, scale factor, or place value has changed. 10⁻² = 1/10² = 1/100 = 0.01. Use this check: Write the reciprocal first.","B":"Choosing “−0.01” suggests the sign rule has been applied incorrectly. 10⁻² = 1/10² = 1/100 = 0.01. Use this check: Write the reciprocal first.","D":"Choosing “−100” suggests the sign rule has been applied incorrectly. 10⁻² = 1/10² = 1/100 = 0.01. Use this check: Write the reciprocal first."}}'::jsonb, '10⁻² = 1/10² = 1/100 = 0.01.', 'procedural', 'routine'),
  ('Q.G9.S4.PRACTICE.EXP-ZERO-NEGATIVE.03', 'Which expression equals 1/p⁵?', '{"type":"multiple_choice","options":{"A":"−p⁵","B":"p⁵","C":"1/5p","D":"p⁻⁵"},"correct_option":"D","distractor_explanations":{"A":"Choosing “−p⁵” suggests the sign rule has been applied incorrectly. By definition, p⁻⁵ = 1/p⁵ for p ≠ 0. Use this check: The negative belongs to the exponent.","B":"Choosing “p⁵” suggests a different operation or condition has been applied than the one in the question. By definition, p⁻⁵ = 1/p⁵ for p ≠ 0. Use this check: The negative belongs to the exponent.","C":"Choosing “1/5p” suggests a different operation or condition has been applied than the one in the question. By definition, p⁻⁵ = 1/p⁵ for p ≠ 0. Use this check: The negative belongs to the exponent."}}'::jsonb, 'By definition, p⁻⁵ = 1/p⁵ for p ≠ 0.', 'mathematical_reasoning', 'complex'),
  ('Q.G9.S4.PRACTICE.EXP-ZERO-NEGATIVE.04', 'Why is 0⁰ not used in the zero-exponent rule?', '{"type":"multiple_choice","options":{"A":"The quotient-law argument would divide 0 by 0","B":"Zero has no powers","C":"It must equal 1","D":"It must equal 0"},"correct_option":"A","distractor_explanations":{"B":"Choosing “Zero has no powers” suggests a different operation or condition has been applied than the one in the question. The rule a⁰ comes from a¹ ÷ a¹, which needs a non-zero base. Use this check: What happens if the denominator is zero?","C":"Choosing “It must equal 1” suggests a calculation step, scale factor, or place value has changed. The rule a⁰ comes from a¹ ÷ a¹, which needs a non-zero base. Use this check: What happens if the denominator is zero?","D":"Choosing “It must equal 0” suggests a calculation step, scale factor, or place value has changed. The rule a⁰ comes from a¹ ÷ a¹, which needs a non-zero base. Use this check: What happens if the denominator is zero?"}}'::jsonb, 'The rule a⁰ comes from a¹ ÷ a¹, which needs a non-zero base.', 'mathematical_reasoning', 'complex'),
  ('Q.G9.S4.PRACTICE.SCI-NOTATION.01', 'Write 72 000 in scientific notation.', '{"type":"multiple_choice","options":{"A":"7.2 × 10⁴","B":"72 × 10³","C":"7.2 × 10³","D":"0.72 × 10⁵"},"correct_option":"A","distractor_explanations":{"B":"Choosing “72 × 10³” suggests a calculation step, scale factor, or place value has changed. Move the decimal four places left: 72 000 = 7.2 × 10⁴. Use this check: Make the first number between 1 and 10.","C":"Choosing “7.2 × 10³” suggests a calculation step, scale factor, or place value has changed. Move the decimal four places left: 72 000 = 7.2 × 10⁴. Use this check: Make the first number between 1 and 10.","D":"Choosing “0.72 × 10⁵” suggests a calculation step, scale factor, or place value has changed. Move the decimal four places left: 72 000 = 7.2 × 10⁴. Use this check: Make the first number between 1 and 10."}}'::jsonb, 'Move the decimal four places left: 72 000 = 7.2 × 10⁴.', 'procedural', 'routine'),
  ('Q.G9.S4.PRACTICE.SCI-NOTATION.02', 'What is 3.6 × 10³ in ordinary notation?', '{"type":"multiple_choice","options":{"A":"0.0036","B":"3 600","C":"360","D":"36 000"},"correct_option":"B","distractor_explanations":{"A":"Choosing “0.0036” suggests a calculation step, scale factor, or place value has changed. 10³ = 1000, so 3.6 × 1000 = 3600. Use this check: A positive exponent makes a larger number.","C":"Choosing “360” suggests a calculation step, scale factor, or place value has changed. 10³ = 1000, so 3.6 × 1000 = 3600. Use this check: A positive exponent makes a larger number.","D":"Choosing “36 000” suggests a calculation step, scale factor, or place value has changed. 10³ = 1000, so 3.6 × 1000 = 3600. Use this check: A positive exponent makes a larger number."}}'::jsonb, '10³ = 1000, so 3.6 × 1000 = 3600.', 'procedural', 'routine'),
  ('Q.G9.S4.PRACTICE.SCI-NOTATION.03', 'Write −0.0042 in standard scientific notation.', '{"type":"multiple_choice","options":{"A":"−4.2 × 10³","B":"−0.42 × 10⁻²","C":"−4.2 × 10⁻³","D":"4.2 × 10⁻³"},"correct_option":"C","distractor_explanations":{"A":"Choosing “−4.2 × 10³” suggests an exponent or operation has been used in place of the required inverse operation. Keep the negative sign. Move the decimal three places right to get −4.2, so use exponent −3; |−4.2| is between 1 and 10. Use this check: Small decimals need negative powers of ten; keep the original sign.","B":"Choosing “−0.42 × 10⁻²” suggests an exponent or operation has been used in place of the required inverse operation. Keep the negative sign. Move the decimal three places right to get −4.2, so use exponent −3; |−4.2| is between 1 and 10. Use this check: Small decimals need negative powers of ten; keep the original sign.","D":"Choosing “4.2 × 10⁻³” suggests an exponent or operation has been used in place of the required inverse operation. Keep the negative sign. Move the decimal three places right to get −4.2, so use exponent −3; |−4.2| is between 1 and 10. Use this check: Small decimals need negative powers of ten; keep the original sign."}}'::jsonb, 'Keep the negative sign. Move the decimal three places right to get −4.2, so use exponent −3; |−4.2| is between 1 and 10.', 'mathematical_reasoning', 'complex'),
  ('Q.G9.S4.PRACTICE.SCI-NOTATION.04', 'Why is 45 × 10⁵ not standard scientific notation?', '{"type":"multiple_choice","options":{"A":"The exponent must be negative","B":"Scientific notation cannot use 10⁵","C":"45 is too small","D":"|45| is not less than 10"},"correct_option":"D","distractor_explanations":{"A":"Choosing “The exponent must be negative” suggests a different operation or condition has been applied than the one in the question. For any nonzero number in standard form, 1 ≤ |a| < 10. Here |45| is too large; rewrite it as 4.5 × 10⁶. Use this check: Check the absolute value of the coefficient.","B":"Choosing “Scientific notation cannot use 10⁵” suggests an absolute statement has replaced the stated mathematical condition. For any nonzero number in standard form, 1 ≤ |a| < 10. Here |45| is too large; rewrite it as 4.5 × 10⁶. Use this check: Check the absolute value of the coefficient.","C":"Choosing “45 is too small” suggests a calculation step, scale factor, or place value has changed. For any nonzero number in standard form, 1 ≤ |a| < 10. Here |45| is too large; rewrite it as 4.5 × 10⁶. Use this check: Check the absolute value of the coefficient."}}'::jsonb, 'For any nonzero number in standard form, 1 ≤ |a| < 10. Here |45| is too large; rewrite it as 4.5 × 10⁶.', 'mathematical_reasoning', 'complex'),
  ('Q.G9.S4.PRACTICE.PATTERN-STRUCTURE.01', 'What is the first difference of 11, 16, 21, 26, …?', '{"type":"multiple_choice","options":{"A":"−5","B":"5","C":"11","D":"10"},"correct_option":"B","distractor_explanations":{"A":"Choosing “−5” suggests the sign rule has been applied incorrectly. 16 − 11 = 5, and the same change continues. Use this check: Subtract consecutive terms.","C":"Choosing “11” suggests a calculation step, scale factor, or place value has changed. 16 − 11 = 5, and the same change continues. Use this check: Subtract consecutive terms.","D":"Choosing “10” suggests a calculation step, scale factor, or place value has changed. 16 − 11 = 5, and the same change continues. Use this check: Subtract consecutive terms."}}'::jsonb, '16 − 11 = 5, and the same change continues.', 'procedural', 'routine'),
  ('Q.G9.S4.PRACTICE.PATTERN-STRUCTURE.02', 'Extend 4, 10, 16, … by two terms.', '{"type":"multiple_choice","options":{"A":"26, 36","B":"18, 20","C":"22, 28","D":"20, 24"},"correct_option":"C","distractor_explanations":{"A":"Choosing “26, 36” suggests a calculation step, scale factor, or place value has changed. The first difference is 6, so add 6 twice. Use this check: Find the constant change.","B":"Choosing “18, 20” suggests a calculation step, scale factor, or place value has changed. The first difference is 6, so add 6 twice. Use this check: Find the constant change.","D":"Choosing “20, 24” suggests a calculation step, scale factor, or place value has changed. The first difference is 6, so add 6 twice. Use this check: Find the constant change."}}'::jsonb, 'The first difference is 6, so add 6 twice.', 'procedural', 'routine'),
  ('Q.G9.S4.PRACTICE.PATTERN-STRUCTURE.03', 'Which statement shows a linear pattern?', '{"type":"multiple_choice","options":{"A":"Its terms are all even","B":"Its ratio is constant","C":"It starts at zero","D":"Its first differences are constant"},"correct_option":"D","distractor_explanations":{"A":"Choosing “Its terms are all even” suggests a different operation or condition has been applied than the one in the question. Constant first differences identify a linear pattern. Use this check: Compare changes, not just values.","B":"Choosing “Its ratio is constant” suggests a different operation or condition has been applied than the one in the question. Constant first differences identify a linear pattern. Use this check: Compare changes, not just values.","C":"Choosing “It starts at zero” suggests a different operation or condition has been applied than the one in the question. Constant first differences identify a linear pattern. Use this check: Compare changes, not just values."}}'::jsonb, 'Constant first differences identify a linear pattern.', 'mathematical_reasoning', 'complex'),
  ('Q.G9.S4.PRACTICE.PATTERN-STRUCTURE.04', 'A table has T1 = 7, T2 = 12, T3 = 17. What is T8?', '{"type":"multiple_choice","options":{"A":"42","B":"37","C":"47","D":"52"},"correct_option":"A","distractor_explanations":{"B":"Choosing “37” suggests a calculation step, scale factor, or place value has changed. The difference is 5. From T1 to T8 there are seven increases: 7 + 7×5 = 42. Use this check: Count the jumps between term 1 and term 8.","C":"Choosing “47” suggests a calculation step, scale factor, or place value has changed. The difference is 5. From T1 to T8 there are seven increases: 7 + 7×5 = 42. Use this check: Count the jumps between term 1 and term 8.","D":"Choosing “52” suggests a calculation step, scale factor, or place value has changed. The difference is 5. From T1 to T8 there are seven increases: 7 + 7×5 = 42. Use this check: Count the jumps between term 1 and term 8."}}'::jsonb, 'The difference is 5. From T1 to T8 there are seven increases: 7 + 7×5 = 42.', 'mathematical_reasoning', 'complex'),
  ('Q.G9.S4.PRACTICE.NTH-TERM.01', 'Find the nth term of 3, 7, 11, …', '{"type":"multiple_choice","options":{"A":"4n − 1","B":"4n + 3","C":"3n + 1","D":"n + 3"},"correct_option":"A","distractor_explanations":{"B":"Choosing “4n + 3” suggests a calculation step, scale factor, or place value has changed. Difference is 4. At n=1, 4+c=3, so c=−1. Use this check: Use the first term to solve for c.","C":"Choosing “3n + 1” suggests a calculation step, scale factor, or place value has changed. Difference is 4. At n=1, 4+c=3, so c=−1. Use this check: Use the first term to solve for c.","D":"Choosing “n + 3” suggests a calculation step, scale factor, or place value has changed. Difference is 4. At n=1, 4+c=3, so c=−1. Use this check: Use the first term to solve for c."}}'::jsonb, 'Difference is 4. At n=1, 4+c=3, so c=−1.', 'procedural', 'routine'),
  ('Q.G9.S4.PRACTICE.NTH-TERM.02', 'For Tn = 5n + 2, find T6.', '{"type":"multiple_choice","options":{"A":"13","B":"32","C":"30","D":"37"},"correct_option":"B","distractor_explanations":{"A":"Choosing “13” suggests a calculation step, scale factor, or place value has changed. Substitute n=6: 5(6)+2=32. Use this check: Put 6 in place of n.","C":"Choosing “30” suggests a calculation step, scale factor, or place value has changed. Substitute n=6: 5(6)+2=32. Use this check: Put 6 in place of n.","D":"Choosing “37” suggests a calculation step, scale factor, or place value has changed. Substitute n=6: 5(6)+2=32. Use this check: Put 6 in place of n."}}'::jsonb, 'Substitute n=6: 5(6)+2=32.', 'procedural', 'routine'),
  ('Q.G9.S4.PRACTICE.NTH-TERM.03', 'Why should you test an nth-term rule using n = 2?', '{"type":"multiple_choice","options":{"A":"It makes c equal zero","B":"It removes the need for n = 1","C":"It checks that the rule fits more than one term","D":"It changes the first difference"},"correct_option":"C","distractor_explanations":{"A":"Choosing “It makes c equal zero” suggests a different operation or condition has been applied than the one in the question. A second test catches a rule that only happens to fit the first term. Use this check: A pattern rule must match the sequence, not one value.","B":"Choosing “It removes the need for n = 1” suggests a different operation or condition has been applied than the one in the question. A second test catches a rule that only happens to fit the first term. Use this check: A pattern rule must match the sequence, not one value.","D":"Choosing “It changes the first difference” suggests a different operation or condition has been applied than the one in the question. A second test catches a rule that only happens to fit the first term. Use this check: A pattern rule must match the sequence, not one value."}}'::jsonb, 'A second test catches a rule that only happens to fit the first term.', 'mathematical_reasoning', 'complex'),
  ('Q.G9.S4.PRACTICE.NTH-TERM.04', 'A learner gives Tn = 3n + 8 for 8, 11, 14, … . What is correct?', '{"type":"multiple_choice","options":{"A":"It should be 8n + 3","B":"It should be 3n","C":"The learner rule is correct","D":"It should be 3n + 5"},"correct_option":"D","distractor_explanations":{"A":"Choosing “It should be 8n + 3” suggests a calculation step, scale factor, or place value has changed. The difference is 3. At n=1, 3+c=8, so c=5. Use this check: Test the learner rule at n=1.","B":"Choosing “It should be 3n” suggests a calculation step, scale factor, or place value has changed. The difference is 3. At n=1, 3+c=8, so c=5. Use this check: Test the learner rule at n=1.","C":"Choosing “The learner rule is correct” suggests a different operation or condition has been applied than the one in the question. The difference is 3. At n=1, 3+c=8, so c=5. Use this check: Test the learner rule at n=1."}}'::jsonb, 'The difference is 3. At n=1, 3+c=8, so c=5.', 'mathematical_reasoning', 'complex'),
  ('Q.G9.S4.PRACTICE.VISUAL-PATTERNS.01', 'How many matchsticks are needed for 4 joined squares in a row?', '{"type":"multiple_choice","options":{"A":"12","B":"16","C":"10","D":"13"},"correct_option":"D","distractor_explanations":{"A":"Choosing “12” suggests a calculation step, scale factor, or place value has changed. M = 3n+1. For n=4, M=13. Use this check: Each new square adds 3, not 4.","B":"Choosing “16” suggests a calculation step, scale factor, or place value has changed. M = 3n+1. For n=4, M=13. Use this check: Each new square adds 3, not 4.","C":"Choosing “10” suggests a calculation step, scale factor, or place value has changed. M = 3n+1. For n=4, M=13. Use this check: Each new square adds 3, not 4."}}'::jsonb, 'M = 3n+1. For n=4, M=13.', 'procedural', 'routine'),
  ('Q.G9.S4.PRACTICE.VISUAL-PATTERNS.02', 'Which rule fits a pattern beginning 5, 8, 11, …?', '{"type":"multiple_choice","options":{"A":"3n + 2","B":"3n + 5","C":"5n + 3","D":"n + 4"},"correct_option":"A","distractor_explanations":{"B":"Choosing “3n + 5” suggests a calculation step, scale factor, or place value has changed. Difference is 3. At n=1, 3+c=5, so c=2. Use this check: Find the difference, then test n=1.","C":"Choosing “5n + 3” suggests a calculation step, scale factor, or place value has changed. Difference is 3. At n=1, 3+c=5, so c=2. Use this check: Find the difference, then test n=1.","D":"Choosing “n + 4” suggests a calculation step, scale factor, or place value has changed. Difference is 3. At n=1, 3+c=5, so c=2. Use this check: Find the difference, then test n=1."}}'::jsonb, 'Difference is 3. At n=1, 3+c=5, so c=2.', 'procedural', 'routine'),
  ('Q.G9.S4.PRACTICE.VISUAL-PATTERNS.03', 'Why does a joined-square row use 3n + 1 instead of 4n?', '{"type":"multiple_choice","options":{"A":"Squares only need three sides","B":"Each added square shares one side","C":"The first square has no sides","D":"n is always one"},"correct_option":"B","distractor_explanations":{"A":"Choosing “Squares only need three sides” suggests a different operation or condition has been applied than the one in the question. The n−1 shared sides mean the total is 4n−(n−1)=3n+1. Use this check: Look at what is shared between neighbours.","C":"Choosing “The first square has no sides” suggests a different operation or condition has been applied than the one in the question. The n−1 shared sides mean the total is 4n−(n−1)=3n+1. Use this check: Look at what is shared between neighbours.","D":"Choosing “n is always one” suggests an absolute statement has replaced the stated mathematical condition. The n−1 shared sides mean the total is 4n−(n−1)=3n+1. Use this check: Look at what is shared between neighbours."}}'::jsonb, 'The n−1 shared sides mean the total is 4n−(n−1)=3n+1.', 'mathematical_reasoning', 'complex'),
  ('Q.G9.S4.PRACTICE.VISUAL-PATTERNS.04', 'A tile pattern has figure 1 = 6 and adds 4 tiles each figure. What is figure 7?', '{"type":"multiple_choice","options":{"A":"34","B":"42","C":"30","D":"28"},"correct_option":"C","distractor_explanations":{"A":"Choosing “34” suggests a calculation step, scale factor, or place value has changed. Tn=6+4(n−1). T7=6+4×6=30. Use this check: There are six increases from figure 1 to figure 7.","B":"Choosing “42” suggests a calculation step, scale factor, or place value has changed. Tn=6+4(n−1). T7=6+4×6=30. Use this check: There are six increases from figure 1 to figure 7.","D":"Choosing “28” suggests a calculation step, scale factor, or place value has changed. Tn=6+4(n−1). T7=6+4×6=30. Use this check: There are six increases from figure 1 to figure 7."}}'::jsonb, 'Tn=6+4(n−1). T7=6+4×6=30.', 'mathematical_reasoning', 'complex'),
  ('Q.G8.S4.PRACTICE.G8-FACTORS.01', 'Simplify 18 ÷ 3 + 4.', '{"type":"multiple_choice","options":{"A":"3","B":"22","C":"10","D":"2"},"correct_option":"C","distractor_explanations":{"A":"Choosing “3” suggests a calculation step, scale factor, or place value has changed. 18 ÷ 3 = 6, then 6 + 4 = 10. Use this check: Divide before adding.","B":"Choosing “22” suggests a calculation step, scale factor, or place value has changed. 18 ÷ 3 = 6, then 6 + 4 = 10. Use this check: Divide before adding.","D":"Choosing “2” suggests a calculation step, scale factor, or place value has changed. 18 ÷ 3 = 6, then 6 + 4 = 10. Use this check: Divide before adding."}}'::jsonb, '18 ÷ 3 = 6, then 6 + 4 = 10.', 'procedural', 'routine'),
  ('Q.G8.S4.PRACTICE.G8-FACTORS.02', 'Which is a factor of 36?', '{"type":"multiple_choice","options":{"A":"8","B":"10","C":"14","D":"9"},"correct_option":"D","distractor_explanations":{"A":"Choosing “8” suggests a calculation step, scale factor, or place value has changed. 36 ÷ 9 = 4 with no remainder. Use this check: A factor divides exactly.","B":"Choosing “10” suggests a calculation step, scale factor, or place value has changed. 36 ÷ 9 = 4 with no remainder. Use this check: A factor divides exactly.","C":"Choosing “14” suggests a calculation step, scale factor, or place value has changed. 36 ÷ 9 = 4 with no remainder. Use this check: A factor divides exactly."}}'::jsonb, '36 ÷ 9 = 4 with no remainder.', 'procedural', 'routine'),
  ('Q.G8.S4.PRACTICE.G8-FACTORS.03', 'Simplify 5 + 3 × 4.', '{"type":"multiple_choice","options":{"A":"17","B":"32","C":"20","D":"12"},"correct_option":"A","distractor_explanations":{"B":"Choosing “32” suggests a calculation step, scale factor, or place value has changed. Multiply 3×4 first, then add 5. Use this check: Multiplication comes before addition.","C":"Choosing “20” suggests a calculation step, scale factor, or place value has changed. Multiply 3×4 first, then add 5. Use this check: Multiplication comes before addition.","D":"Choosing “12” suggests a calculation step, scale factor, or place value has changed. Multiply 3×4 first, then add 5. Use this check: Multiplication comes before addition."}}'::jsonb, 'Multiply 3×4 first, then add 5.', 'mathematical_reasoning', 'complex'),
  ('Q.G8.S4.PRACTICE.G8-FACTORS.04', 'Why is 6 a common factor of 18 and 30?', '{"type":"multiple_choice","options":{"A":"It is a multiple of neither","B":"It divides both without a remainder","C":"It is their sum","D":"It is bigger than both"},"correct_option":"B","distractor_explanations":{"A":"Choosing “It is a multiple of neither” suggests a different operation or condition has been applied than the one in the question. 18 ÷ 6 = 3 and 30 ÷ 6 = 5, so 6 divides both numbers exactly. Use this check: Test division for each number.","C":"Choosing “It is their sum” suggests a different operation or condition has been applied than the one in the question. 18 ÷ 6 = 3 and 30 ÷ 6 = 5, so 6 divides both numbers exactly. Use this check: Test division for each number.","D":"Choosing “It is bigger than both” suggests a different operation or condition has been applied than the one in the question. 18 ÷ 6 = 3 and 30 ÷ 6 = 5, so 6 divides both numbers exactly. Use this check: Test division for each number."}}'::jsonb, '18 ÷ 6 = 3 and 30 ÷ 6 = 5, so 6 divides both numbers exactly.', 'mathematical_reasoning', 'complex'),
  ('Q.G8.S4.PRACTICE.G8-FRACTIONS.01', 'Calculate 1/4 + 2/4.', '{"type":"multiple_choice","options":{"A":"3/4","B":"3/8","C":"2/8","D":"1/2"},"correct_option":"A","distractor_explanations":{"B":"Choosing “3/8” suggests a calculation step, scale factor, or place value has changed. The denominators match, so add the numerators. Use this check: Keep the denominator 4.","C":"Choosing “2/8” suggests a calculation step, scale factor, or place value has changed. The denominators match, so add the numerators. Use this check: Keep the denominator 4.","D":"Choosing “1/2” suggests a calculation step, scale factor, or place value has changed. The denominators match, so add the numerators. Use this check: Keep the denominator 4."}}'::jsonb, 'The denominators match, so add the numerators.', 'procedural', 'routine'),
  ('Q.G8.S4.PRACTICE.G8-FRACTIONS.02', 'Write 3/5 with denominator 20.', '{"type":"multiple_choice","options":{"A":"8/20","B":"12/20","C":"3/20","D":"15/20"},"correct_option":"B","distractor_explanations":{"A":"Choosing “8/20” suggests a calculation step, scale factor, or place value has changed. Multiply numerator and denominator by 4. Use this check: What makes 5 into 20?","C":"Choosing “3/20” suggests a calculation step, scale factor, or place value has changed. Multiply numerator and denominator by 4. Use this check: What makes 5 into 20?","D":"Choosing “15/20” suggests a calculation step, scale factor, or place value has changed. Multiply numerator and denominator by 4. Use this check: What makes 5 into 20?"}}'::jsonb, 'Multiply numerator and denominator by 4.', 'procedural', 'routine'),
  ('Q.G8.S4.PRACTICE.G8-FRACTIONS.03', 'Calculate 2/3 − 1/6.', '{"type":"multiple_choice","options":{"A":"1/3","B":"1/18","C":"1/2","D":"1/6"},"correct_option":"C","distractor_explanations":{"A":"Choosing “1/3” suggests a calculation step, scale factor, or place value has changed. 2/3=4/6. 4/6−1/6=3/6=1/2. Use this check: Use denominator 6.","B":"Choosing “1/18” suggests a calculation step, scale factor, or place value has changed. 2/3=4/6. 4/6−1/6=3/6=1/2. Use this check: Use denominator 6.","D":"Choosing “1/6” suggests a calculation step, scale factor, or place value has changed. 2/3=4/6. 4/6−1/6=3/6=1/2. Use this check: Use denominator 6."}}'::jsonb, '2/3=4/6. 4/6−1/6=3/6=1/2.', 'mathematical_reasoning', 'complex'),
  ('Q.G8.S4.PRACTICE.G8-FRACTIONS.04', 'Why is 2/4 equal to 1/2?', '{"type":"multiple_choice","options":{"A":"The denominators are added","B":"The numerator is smaller than the denominator","C":"Fractions cannot be simplified","D":"Dividing both numerator and denominator by 2 gives 1/2"},"correct_option":"D","distractor_explanations":{"A":"Choosing “The denominators are added” suggests a different operation or condition has been applied than the one in the question. Divide numerator and denominator of 2/4 by the same non-zero number: 2÷2 / 4÷2 = 1/2. Use this check: Simplify both parts by the same factor.","B":"Choosing “The numerator is smaller than the denominator” suggests a different operation or condition has been applied than the one in the question. Divide numerator and denominator of 2/4 by the same non-zero number: 2÷2 / 4÷2 = 1/2. Use this check: Simplify both parts by the same factor.","C":"Choosing “Fractions cannot be simplified” suggests an absolute statement has replaced the stated mathematical condition. Divide numerator and denominator of 2/4 by the same non-zero number: 2÷2 / 4÷2 = 1/2. Use this check: Simplify both parts by the same factor."}}'::jsonb, 'Divide numerator and denominator of 2/4 by the same non-zero number: 2÷2 / 4÷2 = 1/2.', 'mathematical_reasoning', 'complex'),
  ('Q.G8.S4.PRACTICE.G8-DECIMALS.01', 'Calculate 6.2 − 1.45.', '{"type":"multiple_choice","options":{"A":"5.25","B":"4.65","C":"4.85","D":"4.75"},"correct_option":"D","distractor_explanations":{"A":"Choosing “5.25” suggests a calculation step, scale factor, or place value has changed. Write 6.2 as 6.20, then subtract: 6.20 − 1.45 = 4.75. Use this check: Write 6.2 as 6.20.","B":"Choosing “4.65” suggests a calculation step, scale factor, or place value has changed. Write 6.2 as 6.20, then subtract: 6.20 − 1.45 = 4.75. Use this check: Write 6.2 as 6.20.","C":"Choosing “4.85” suggests a calculation step, scale factor, or place value has changed. Write 6.2 as 6.20, then subtract: 6.20 − 1.45 = 4.75. Use this check: Write 6.2 as 6.20."}}'::jsonb, 'Write 6.2 as 6.20, then subtract: 6.20 − 1.45 = 4.75.', 'procedural', 'routine'),
  ('Q.G8.S4.PRACTICE.G8-DECIMALS.02', 'Calculate 0.4 × 0.5.', '{"type":"multiple_choice","options":{"A":"0.2","B":"2","C":"0.02","D":"0.9"},"correct_option":"A","distractor_explanations":{"B":"Choosing “2” suggests a calculation step, scale factor, or place value has changed. 4×5=20; two decimal places give 0.20. Use this check: Estimate whether multiplying two numbers smaller than one should make the result larger or smaller.","C":"Choosing “0.02” suggests a calculation step, scale factor, or place value has changed. 4×5=20; two decimal places give 0.20. Use this check: Estimate whether multiplying two numbers smaller than one should make the result larger or smaller.","D":"Choosing “0.9” suggests a calculation step, scale factor, or place value has changed. 4×5=20; two decimal places give 0.20. Use this check: Estimate whether multiplying two numbers smaller than one should make the result larger or smaller."}}'::jsonb, '4×5=20; two decimal places give 0.20.', 'procedural', 'routine'),
  ('Q.G8.S4.PRACTICE.G8-DECIMALS.03', 'A R12.50 item costs how much for 3?', '{"type":"multiple_choice","options":{"A":"R125.00","B":"R37.50","C":"R15.50","D":"R36.50"},"correct_option":"B","distractor_explanations":{"A":"Choosing “R125.00” suggests a calculation step, scale factor, or place value has changed. Multiply R12.50 by 3: 12.50 × 3 = 37.50, so the total is R37.50. Use this check: Multiply the amount, keeping cents.","C":"Choosing “R15.50” suggests a calculation step, scale factor, or place value has changed. Multiply R12.50 by 3: 12.50 × 3 = 37.50, so the total is R37.50. Use this check: Multiply the amount, keeping cents.","D":"Choosing “R36.50” suggests a calculation step, scale factor, or place value has changed. Multiply R12.50 by 3: 12.50 × 3 = 37.50, so the total is R37.50. Use this check: Multiply the amount, keeping cents."}}'::jsonb, 'Multiply R12.50 by 3: 12.50 × 3 = 37.50, so the total is R37.50.', 'mathematical_reasoning', 'complex'),
  ('Q.G8.S4.PRACTICE.G8-DECIMALS.04', 'Why is estimating useful with decimals?', '{"type":"multiple_choice","options":{"A":"It removes units","B":"It makes all answers whole","C":"It can reveal a misplaced decimal point","D":"It replaces calculation"},"correct_option":"C","distractor_explanations":{"A":"Choosing “It removes units” suggests a different operation or condition has been applied than the one in the question. An answer near 20 for 0.4×0.5 is unreasonable; estimate catches it. Use this check: Think about the size of the answer.","B":"Choosing “It makes all answers whole” suggests a different operation or condition has been applied than the one in the question. An answer near 20 for 0.4×0.5 is unreasonable; estimate catches it. Use this check: Think about the size of the answer.","D":"Choosing “It replaces calculation” suggests a different operation or condition has been applied than the one in the question. An answer near 20 for 0.4×0.5 is unreasonable; estimate catches it. Use this check: Think about the size of the answer."}}'::jsonb, 'An answer near 20 for 0.4×0.5 is unreasonable; estimate catches it.', 'mathematical_reasoning', 'complex'),
  ('Q.G8.S4.PRACTICE.G8-INTEGERS.01', 'Calculate −9 + 4.', '{"type":"multiple_choice","options":{"A":"5","B":"−13","C":"13","D":"−5"},"correct_option":"D","distractor_explanations":{"A":"Choosing “5” suggests a calculation step, scale factor, or place value has changed. Move four right from −9 to −5. Use this check: The negative magnitude is larger.","B":"Choosing “−13” suggests a calculation step, scale factor, or place value has changed. Move four right from −9 to −5. Use this check: The negative magnitude is larger.","C":"Choosing “13” suggests a calculation step, scale factor, or place value has changed. Move four right from −9 to −5. Use this check: The negative magnitude is larger."}}'::jsonb, 'Move four right from −9 to −5.', 'procedural', 'routine'),
  ('Q.G8.S4.PRACTICE.G8-INTEGERS.02', 'Calculate (−5) × (−3).', '{"type":"multiple_choice","options":{"A":"15","B":"−15","C":"−8","D":"8"},"correct_option":"A","distractor_explanations":{"B":"Choosing “−15” suggests the sign rule has been applied incorrectly. Same signs give positive; 5×3=15. Use this check: Two negatives make a positive product.","C":"Choosing “−8” suggests the sign rule has been applied incorrectly. Same signs give positive; 5×3=15. Use this check: Two negatives make a positive product.","D":"Choosing “8” suggests a calculation step, scale factor, or place value has changed. Same signs give positive; 5×3=15. Use this check: Two negatives make a positive product."}}'::jsonb, 'Same signs give positive; 5×3=15.', 'procedural', 'routine'),
  ('Q.G8.S4.PRACTICE.G8-INTEGERS.03', 'Calculate 7 − (−2).', '{"type":"multiple_choice","options":{"A":"−5","B":"9","C":"5","D":"−9"},"correct_option":"B","distractor_explanations":{"A":"Choosing “−5” suggests the sign rule has been applied incorrectly. Subtracting −2 means add 2: 7+2=9. Use this check: Rewrite as addition.","C":"Choosing “5” suggests a calculation step, scale factor, or place value has changed. Subtracting −2 means add 2: 7+2=9. Use this check: Rewrite as addition.","D":"Choosing “−9” suggests the sign rule has been applied incorrectly. Subtracting −2 means add 2: 7+2=9. Use this check: Rewrite as addition."}}'::jsonb, 'Subtracting −2 means add 2: 7+2=9.', 'mathematical_reasoning', 'complex'),
  ('Q.G8.S4.PRACTICE.G8-INTEGERS.04', 'Why is (−12) ÷ 3 negative?', '{"type":"multiple_choice","options":{"A":"Both numbers are negative","B":"12 is greater than 3","C":"The signs are different","D":"Division ignores signs"},"correct_option":"C","distractor_explanations":{"A":"Choosing “Both numbers are negative” suggests a different operation or condition has been applied than the one in the question. A negative divided by a positive is negative. Use this check: Compare the signs first.","B":"Choosing “12 is greater than 3” suggests a different operation or condition has been applied than the one in the question. A negative divided by a positive is negative. Use this check: Compare the signs first.","D":"Choosing “Division ignores signs” suggests a different operation or condition has been applied than the one in the question. A negative divided by a positive is negative. Use this check: Compare the signs first."}}'::jsonb, 'A negative divided by a positive is negative.', 'mathematical_reasoning', 'complex'),
  ('Q.G8.S4.PRACTICE.G8-EXPONENTS.01', 'What is 2⁴?', '{"type":"multiple_choice","options":{"A":"16","B":"8","C":"6","D":"24"},"correct_option":"A","distractor_explanations":{"B":"Choosing “8” suggests a calculation step, scale factor, or place value has changed. The exponent 4 means four factors: 2 × 2 × 2 × 2 = 16. Use this check: Write four factors of 2.","C":"Choosing “6” suggests a calculation step, scale factor, or place value has changed. The exponent 4 means four factors: 2 × 2 × 2 × 2 = 16. Use this check: Write four factors of 2.","D":"Choosing “24” suggests a calculation step, scale factor, or place value has changed. The exponent 4 means four factors: 2 × 2 × 2 × 2 = 16. Use this check: Write four factors of 2."}}'::jsonb, 'The exponent 4 means four factors: 2 × 2 × 2 × 2 = 16.', 'procedural', 'routine'),
  ('Q.G8.S4.PRACTICE.G8-EXPONENTS.02', 'Simplify x² × x⁵.', '{"type":"multiple_choice","options":{"A":"x³","B":"x⁷","C":"x¹⁰","D":"2x⁷"},"correct_option":"B","distractor_explanations":{"A":"Choosing “x³” suggests a different operation or condition has been applied than the one in the question. Same base product: add 2+5. Use this check: Keep the base x.","C":"Choosing “x¹⁰” suggests a different operation or condition has been applied than the one in the question. Same base product: add 2+5. Use this check: Keep the base x.","D":"Choosing “2x⁷” suggests a different operation or condition has been applied than the one in the question. Same base product: add 2+5. Use this check: Keep the base x."}}'::jsonb, 'Same base product: add 2+5.', 'procedural', 'routine'),
  ('Q.G8.S4.PRACTICE.G8-EXPONENTS.03', 'What is the base in (−4)³?', '{"type":"multiple_choice","options":{"A":"4 only","B":"−3","C":"−4","D":"3"},"correct_option":"C","distractor_explanations":{"A":"Choosing “4 only” suggests a calculation step, scale factor, or place value has changed. Brackets make the complete signed number the base. Use this check: The exponent sits outside the bracket.","B":"Choosing “−3” suggests a calculation step, scale factor, or place value has changed. Brackets make the complete signed number the base. Use this check: The exponent sits outside the bracket.","D":"Choosing “3” suggests a calculation step, scale factor, or place value has changed. Brackets make the complete signed number the base. Use this check: The exponent sits outside the bracket."}}'::jsonb, 'Brackets make the complete signed number the base.', 'mathematical_reasoning', 'complex'),
  ('Q.G8.S4.PRACTICE.G8-EXPONENTS.04', 'Why is a³ × a² not a⁶?', '{"type":"multiple_choice","options":{"A":"Bases are added","B":"The base changes to 6","C":"It is always a⁶","D":"The exponents are added, not multiplied"},"correct_option":"D","distractor_explanations":{"A":"Choosing “Bases are added” suggests a different operation or condition has been applied than the one in the question. There are 3+2 factors of a, giving a⁵. Use this check: Count the total factors.","B":"Choosing “The base changes to 6” suggests a different operation or condition has been applied than the one in the question. There are 3+2 factors of a, giving a⁵. Use this check: Count the total factors.","C":"Choosing “It is always a⁶” suggests an absolute statement has replaced the stated mathematical condition. There are 3+2 factors of a, giving a⁵. Use this check: Count the total factors."}}'::jsonb, 'There are 3+2 factors of a, giving a⁵.', 'mathematical_reasoning', 'complex'),
  ('Q.G8.S4.PRACTICE.G8-PATTERNS.01', 'What comes next: 9, 13, 17, …?', '{"type":"multiple_choice","options":{"A":"19","B":"20","C":"22","D":"21"},"correct_option":"D","distractor_explanations":{"A":"Choosing “19” suggests a calculation step, scale factor, or place value has changed. The constant difference is 4. Use this check: Subtract consecutive terms.","B":"Choosing “20” suggests a calculation step, scale factor, or place value has changed. The constant difference is 4. Use this check: Subtract consecutive terms.","C":"Choosing “22” suggests a calculation step, scale factor, or place value has changed. The constant difference is 4. Use this check: Subtract consecutive terms."}}'::jsonb, 'The constant difference is 4.', 'procedural', 'routine'),
  ('Q.G8.S4.PRACTICE.G8-PATTERNS.02', 'For Tn=2n+1, find T4.', '{"type":"multiple_choice","options":{"A":"9","B":"7","C":"8","D":"12"},"correct_option":"A","distractor_explanations":{"B":"Choosing “7” suggests a calculation step, scale factor, or place value has changed. Substitute n = 4: T4 = 2(4) + 1 = 9. Use this check: Substitute n=4.","C":"Choosing “8” suggests a calculation step, scale factor, or place value has changed. Substitute n = 4: T4 = 2(4) + 1 = 9. Use this check: Substitute n=4.","D":"Choosing “12” suggests a calculation step, scale factor, or place value has changed. Substitute n = 4: T4 = 2(4) + 1 = 9. Use this check: Substitute n=4."}}'::jsonb, 'Substitute n = 4: T4 = 2(4) + 1 = 9.', 'procedural', 'routine'),
  ('Q.G8.S4.PRACTICE.G8-PATTERNS.03', 'Which rule fits 4, 7, 10, …?', '{"type":"multiple_choice","options":{"A":"n + 3","B":"3n + 1","C":"3n + 4","D":"4n − 1"},"correct_option":"B","distractor_explanations":{"A":"Choosing “n + 3” suggests a calculation step, scale factor, or place value has changed. Difference is 3 and 3(1)+1=4. Use this check: Test n=1.","C":"Choosing “3n + 4” suggests a calculation step, scale factor, or place value has changed. Difference is 3 and 3(1)+1=4. Use this check: Test n=1.","D":"Choosing “4n − 1” suggests a calculation step, scale factor, or place value has changed. Difference is 3 and 3(1)+1=4. Use this check: Test n=1."}}'::jsonb, 'Difference is 3 and 3(1)+1=4.', 'mathematical_reasoning', 'complex'),
  ('Q.G8.S4.PRACTICE.G8-PATTERNS.04', 'Why test a rule at n=2?', '{"type":"multiple_choice","options":{"A":"It removes the difference","B":"All rules work at n=2","C":"It confirms another term matches","D":"It changes n into 1"},"correct_option":"C","distractor_explanations":{"A":"Choosing “It removes the difference” suggests a different operation or condition has been applied than the one in the question. A second value can show whether a rule was fitted incorrectly. Use this check: Substitute n=2.","B":"Choosing “All rules work at n=2” suggests a different operation or condition has been applied than the one in the question. A second value can show whether a rule was fitted incorrectly. Use this check: Substitute n=2.","D":"Choosing “It changes n into 1” suggests a different operation or condition has been applied than the one in the question. A second value can show whether a rule was fitted incorrectly. Use this check: Substitute n=2."}}'::jsonb, 'A second value can show whether a rule was fitted incorrectly.', 'mathematical_reasoning', 'complex')
)
insert into public.question_versions(question_item_id,version_number,review_status,activity_type,cognitive_level,representation,difficulty,reasoning_classification,calculator_policy,prompt,answer_config,solution,marks,material_change_note)
select item.id,2,'draft','guided_practice',authored.cognitive_level::public.caps_cognitive_level,'symbolic',case when authored.reasoning_classification='mathematical_reasoning' then 3 else 2 end,authored.reasoning_classification,'not_allowed',authored.prompt,authored.answer_config,authored.solution,1,'Sprint 4 v2 mathematics correction: revised terminology, conditions, answer feedback and/or solution. Version 1 retained for audit.'
from authored join public.question_items item on item.item_code=authored.item_code
join public.question_versions version_one on version_one.question_item_id=item.id and version_one.version_number=1
on conflict(question_item_id,version_number) do nothing;

